			table_col_direction: "Hướng / Người hưởng lợi",
			table_r1_a: "Sự phân bố dân số trên các khu vực (càng chặt càng tốt)",
			table_r1_b: "3.180",
			table_r1_c: "4.707 — rộng hơn 48%",
