			table_r3_d: "<strong>UCP</strong> (Phá vỡ sức mạnh đô thị/ngoại ô)",
			table_r4_a: "Ranh giới tuân theo các đường đô thị hiện có",
			table_r4_b: "80% — trong tiêu chuẩn",
			table_r4_c: "72% — trong tiêu chuẩn",
			table_r4_d: "Không áp dụng — cả hai trong tiêu chuẩn Canada (70–85%)",
			table_r5_a: "Các ranh giới được chủ tịch ủy ban gắn cờ",
			table_r5_b: "0",
			table_r5_c: "3",
			table_r5_d: "Không áp dụng",
			table_r6_a: "Ghế ở mức bỏ phiếu 50/50 (phân vị trong mô phỏng 1.010.000 bản đồ)",
			table_r6_b: "46,1% — p78 (phạm vi bình thường)",
